<div class="dashboard-heading"><div><span class="eyebrow">MARKETPLACE</span><h2>Lojas</h2><p>Cada loja possui um vendedor responsável; um vendedor pode administrar várias lojas.</p></div><a class="button button--primary" href="<?= e(url('/admin/lojas/nova')) ?>">Criar loja</a></div>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Loja</th><th>Vendedor</th><th>Produtos</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($stores as $store): ?><tr><td><strong><?= e($store['name']) ?></strong><small class="table-subtitle"><?= e($store['slug']) ?></small></td><td><?= e($store['seller_name']) ?></td><td><?= (int)$store['products'] ?></td><td><?php $status=$store['status'];require dirname(__DIR__,2).'/components/dashboard/status-badge.php';?></td><td><div class="table-actions"><a href="<?= e(url('/admin/lojas/'.$store['id'].'/editar')) ?>">Editar</a><?php if($store['status']==='active'): ?><form method="post" action="<?= e(url('/admin/lojas/'.$store['id'].'/inativar')) ?>"><?= csrf_field() ?><button>Inativar</button></form><?php endif; ?><form method="post" action="<?= e(url('/admin/lojas/'.$store['id'])) ?>" onsubmit="return confirm('Excluir esta loja?')"><?= csrf_field() ?><input type="hidden" name="_method" value="DELETE"><button class="link-danger">Excluir</button></form></div></td></tr><?php endforeach; ?></tbody></table></div></section>
